<script lang="ts">import { getContext } from "svelte";
import { Button } from "@svar-ui/svelte-core";
const store = getContext("calendar-api");
function addEvent() {
	store.exec("add-event", {
		event: {},
		edit: true
	});
}
</script>

<Button icon="wxi-plus" type="primary" onclick={addEvent}></Button>
